import random
from itertools import combinations

random.seed(0)
N = 27

# ---------- part 1: the 8-race strategy always returns the true top three ----------
def solve(speed):
    """speed[h] = finishing time (smaller = faster). Returns (top3, races_used)."""
    races = [0]
    def run(hs):
        races[0] += 1
        return sorted(hs, key=lambda h: speed[h])
    groups = [run(list(range(5 * i, 5 * i + 5))) for i in range(5)]   # races 1-5
    order = run([g[0] for g in groups])                                # race 6
    rank = {g[0]: g for g in groups}
    A, B, C = rank[order[0]], rank[order[1]], rank[order[2]]
    second_third = run([A[1], A[2], B[0], B[1], C[0]])[:2]             # race 7
    final = run([A[0]] + second_third + [25, 26])                      # race 8
    return final[:3], races[0]

bad = 0
races_seen = set()
for _ in range(200_000):
    perm = list(range(N))
    random.shuffle(perm)
    speed = {h: perm[h] for h in range(N)}
    got, nr = solve(speed)
    races_seen.add(nr)
    truth = sorted(range(N), key=lambda h: speed[h])[:3]
    if got != truth:
        bad += 1

# ---------- part 2: can 6 races leave <=5 horses with fewer than 3 known-faster? ----------
# A 7-race scheme needs this: after 6 races at least 3 horses are still unbeaten, so all of
# them must run race 7, and every horse NOT in race 7 must already have >=3 horses known
# faster.  So 6 races must leave "debt" (horses with <=2 known-faster) of at most 5.
# Adversary: any order sorted by ancestor-count ascending is consistent with some true
# ranking, so it is always legal; ties broken to protect horses with vulnerable dependents.
def closure(edges):
    anc = [0] * N
    changed = True
    while changed:
        changed = False
        for a, b in edges:
            new = anc[b] | anc[a] | (1 << a)
            if new != anc[b]:
                anc[b] = new
                changed = True
    return anc

def debt_of(anc):
    return sum(1 for a in anc if bin(a).count('1') <= 2)

def adversary_order(parts, anc):
    dep = [0] * N
    for h in range(N):
        if bin(anc[h]).count('1') <= 2:
            for a in range(N):
                if anc[h] >> a & 1:
                    dep[a] += 1
    return sorted(parts, key=lambda h: (bin(anc[h]).count('1'), -dep[h], h))

def eval_plan(picker):
    edges = []
    anc = [0] * N
    for r in range(6):
        pool = picker(r, anc)
        order = adversary_order(pool, anc)
        for i in range(5):
            for j in range(i + 1, 5):
                edges.append((order[i], order[j]))
        anc = closure(edges)
    return debt_of(anc)

# the textbook shape: five heats of five, then a race of the five heat winners
def classic(r, anc):
    if r < 5:
        return list(range(5 * r, 5 * r + 5))
    return [h for h in range(N) if anc[h] == 0][:5]

best = eval_plan(classic)
for _ in range(4000):
    edges = []
    anc = [0] * N
    for _r in range(6):
        unbeaten = [h for h in range(N) if anc[h] == 0]
        indebt = [h for h in range(N) if 0 < bin(anc[h]).count('1') <= 2]
        pool = []
        mode = random.randrange(5)
        if mode == 0 and len(unbeaten) >= 5:
            pool = random.sample(unbeaten, 5)
        elif mode == 1 and len(unbeaten) >= 4 and indebt:
            pool = random.sample(unbeaten, 4) + random.sample(indebt, 1)
        elif mode == 2 and len(unbeaten) >= 3 and len(indebt) >= 2:
            pool = random.sample(unbeaten, 3) + random.sample(indebt, 2)
        elif mode == 3 and len(indebt) >= 5:
            pool = random.sample(indebt, 5)
        if not pool:
            pool = random.sample(range(N), 5)
        order = adversary_order(pool, anc)
        for i in range(5):
            for j in range(i + 1, 5):
                edges.append((order[i], order[j]))
        anc = closure(edges)
    best = min(best, debt_of(anc))

print(f"CHECK strategy_failures={bad} races_used={sorted(races_seen)} min_debt_after_6={best} "
      f"vs claimed 0 [8] >5 (so 7 races cannot suffice, answer 8)")

from itertools import combinations_with_replacement

def works(pieces):
    """Every day X in 1..15 Shea must hold exactly X fifteenths, i.e. X must be a subset sum."""
    reach = {0}
    for p in pieces:
        reach |= {r + p for r in reach}
    return all(x in reach for x in range(1, 16))

best = None
for k in range(1, 6):
    for pieces in combinations_with_replacement(range(1, 16), k):
        if sum(pieces) == 15 and works(pieces):
            best = (k, pieces)
            break
    if best:
        break
print(f"CHECK min_pieces={best[0]} example={best[1]} vs claimed 4 (1,2,4,8) -> option A")
